gvz(){return"\u064a\u062d\u062f\u062f \u0645\u0643\u0627\u0646 \u0644\u0648\u062d\u0629 \u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0623\u062f\u0627\u0629 \u0623\u0648 \u0627\u0644\u0639\u0646\u0635\u0631 \u0627\u0644\u0645\u062d\u062f\u062f."},
guh(){return"\u064a\u0639\u0631\u0636 \u0634\u0631\u064a\u0637 \u062a\u0646\u0642\u0644 \u062f\u0627\u0626\u0645 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0648\u0627\u0633\u0639\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0633\u0631\u064a\u0639 \u0625\u0644\u0649 \u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a."},
